/**
 * Groq LLM Client
 * Calls the Groq OpenAI-compatible chat completions API.
 */

const DEFAULT_GROQ_API_URL = "https://genailab.tcs.in/v1/chat/completions";
process.env.NODE_TLS_REJECT_UNAUTHORIZED = "0";
const DEFAULT_USER_AGENT = "JavaInterviewQuestionGenerator/1.0";

/**
 * Strip markdown code fences and extract JSON from raw LLM output.
 */
function parseJsonOnly(raw) {
  let cleaned = String(raw || "").trim();

  // Strip <think> blocks generated by some models (like DeepSeek or Qwen)
  cleaned = cleaned.replace(/<think>[\s\S]*?<\/think>/gi, "").trim();

  cleaned = cleaned
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");
    if (start === -1 || end === -1 || end <= start) {
      const arrStart = cleaned.indexOf("[");
      const arrEnd = cleaned.lastIndexOf("]");
      if (arrStart === -1 || arrEnd === -1 || arrEnd <= arrStart) {
        throw new Error("LLM_JSON_PARSE_ERROR");
      }
      return JSON.parse(cleaned.slice(arrStart, arrEnd + 1));
    }
    return JSON.parse(cleaned.slice(start, end + 1));
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

let keyRotateCounter = 0;
function getApiKey(apiKeyEnv = "GROQ_API_KEY") {
  if (apiKeyEnv !== "GROQ_API_KEY" && process.env[apiKeyEnv]) {
    return process.env[apiKeyEnv];
  }
  
  const keys = [];
  if (process.env.GROQ_API_KEY) keys.push(process.env.GROQ_API_KEY);
  if (process.env.GROQ_API_KEY_2) keys.push(process.env.GROQ_API_KEY_2);
  
  if (keys.length === 0) {
    throw new Error(`GROQ_API_KEY is not set in environment variables.`);
  }
  
  const selectedKey = keys[keyRotateCounter % keys.length];
  keyRotateCounter++;
  return selectedKey;
}

function getRateLimitWaitMs(response, body) {
  let waitMs = 30000;
  const retryAfter = response.headers.get("retry-after");
  
  if (retryAfter) {
    const parsed = Number(retryAfter);
    if (Number.isFinite(parsed)) {
      waitMs = Math.max(1000, parsed * 1000);
    }
  } else {
    const text = String(body || "");
    const millisecondsMatch = text.match(/try again in\s+([0-9.]+)\s*ms/i);
    if (millisecondsMatch) {
      waitMs = Math.max(1000, Number(millisecondsMatch[1]) + 1000);
    } else {
      const durationMatch = text.match(/try again in\s+((?:(?:\d+(?:\.\d+)?)\s*h\s*)?(?:(?:\d+(?:\.\d+)?)\s*m(?!s)\s*)?(?:(?:\d+(?:\.\d+)?)\s*s\s*)?)/i);
      if (durationMatch?.[1]?.trim()) {
        const durationText = durationMatch[1];
        const hours = Number(durationText.match(/(\d+(?:\.\d+)?)\s*h/i)?.[1] || 0);
        const minutes = Number(durationText.match(/(\d+(?:\.\d+)?)\s*m(?!s)/i)?.[1] || 0);
        const seconds = Number(durationText.match(/(\d+(?:\.\d+)?)\s*s/i)?.[1] || 0);
        const calcMs = ((hours * 3600) + (minutes * 60) + seconds + 1) * 1000;
        if (Number.isFinite(calcMs) && calcMs > 0) {
          waitMs = Math.max(1000, calcMs);
        }
      } else {
        const secondsMatch = text.match(/try again in\s+([0-9.]+)s/i);
        if (secondsMatch) {
          waitMs = Math.max(1000, (Number(secondsMatch[1]) + 1) * 1000);
        }
      }
    }
  }

  // Clamp to max 30s
  waitMs = Math.min(30000, waitMs);
  
  // Add 10-20% jitter
  const jitter = waitMs * (0.1 + Math.random() * 0.1);
  return waitMs + jitter;
}

function isTransientProviderStatus(status, bodyText = "") {
  if (status === 429) {
    const text = String(bodyText).toLowerCase();
    if (text.includes("tokens per day") || text.includes("(tpd)")) {
      return false; // Hard daily limit, not transient
    }
    return true;
  }
  return status === 408 || status === 409 || status === 425 || status >= 500;
}

function isRateLimitBody(body) {
  const text = String(body || "").toLowerCase();
  return (
    text.includes("rate_limit_exceeded") ||
    text.includes("tokens per minute") ||
    text.includes("tpm") ||
    text.includes("rate limit")
  );
}

function isRetryableRateLimit(response, bodyText) {
  if (response.status === 429) {
    const text = String(bodyText || "").toLowerCase();
    if (text.includes("tokens per day") || text.includes("(tpd)")) {
      return false; // Hard daily limit
    }
    return true;
  }
  return (response.status === 413 && isRateLimitBody(bodyText));
}

function getBackoffWaitMs(attempt) {
  const baseMs = Math.min(30000, 2000 * Math.pow(2, attempt));
  const jitter = baseMs * (0.1 + Math.random() * 0.1);
  return baseMs + jitter;
}

async function callChatCompletion({
  apiKeyEnv = "GROQ_API_KEY",
  apiUrl,
  maxTokens = 1200,
  model,
  fallbackModel,
  retryAttempts = 2,
  systemPrompt,
  temperature = 0,
  timeoutSeconds = 60,
  userAgent = DEFAULT_USER_AGENT,
  userPrompt,
  taskName = "UNKNOWN_TASK",
  jsonMode = false
}) {
  const resolvedApiUrl = apiUrl || process.env.GROQ_API_URL || "https://genailab.tcs.in/v1/chat/completions";
  let currentModel = model;
  const resolvedApiKey = getApiKey(apiKeyEnv);
  const attempts = Math.min(3, Math.max(0, parseInt(retryAttempts, 10) || 0)); // max 3 attempts
  const timeoutMs = Math.max(1, Number(timeoutSeconds) || 60) * 1000;
  
  // Track original fallback logic internally to avoid infinite loops if it resets.
  let usedFallback = false;

  for (let attempt = 0; attempt <= attempts; attempt++) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    let response;
    let bodyText = "";

    try {
      console.log(`[LLMClient] Task: ${taskName} Model: ${currentModel} Attempt: ${attempt + 1}/${attempts + 1}`);
      response = await fetch(resolvedApiUrl, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${resolvedApiKey}`,
          Accept: "application/json",
          "Content-Type": "application/json",
          "User-Agent": userAgent,
        },
        body: JSON.stringify({
          model: currentModel,
          temperature: 1,
          max_tokens: maxTokens,
          response_format: jsonMode ? { type: "json_object" } : undefined,
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ],
        }),
        signal: controller.signal,
      });
      bodyText = await response.text();
    } catch (err) {
      clearTimeout(timeoutId);
      
      if (attempt < attempts) {
        const waitMs = getBackoffWaitMs(attempt);
        console.warn(`[LLMClient] Request failed (${err.message}). Waiting ${Math.round(waitMs / 1000)}s before retrying...`);
        await sleep(waitMs);
        continue;
      }
      
      if (fallbackModel && currentModel !== fallbackModel && !usedFallback) {
        console.warn(`\n[LLMClient]\n${taskName} failed\nModel: ${currentModel}\nReason: ${err.message || "NETWORK_ERROR"}\nFallback: ${fallbackModel}\n`);
        currentModel = fallbackModel;
        attempt = -1; // Reset attempt counter for fallback model
        usedFallback = true;
        continue;
      }
      
      throw err;
    } finally {
      clearTimeout(timeoutId);
    }

    if (!response.ok) {
      if (attempt < attempts && (isRetryableRateLimit(response, bodyText) || isTransientProviderStatus(response.status, bodyText))) {
        const waitMs = isRetryableRateLimit(response, bodyText) ? getRateLimitWaitMs(response, bodyText) : getBackoffWaitMs(attempt);
        
        if (waitMs > 60000 && fallbackModel && currentModel !== fallbackModel && !usedFallback) {
          console.warn(`\n[LLMClient]\n${taskName} rate limit requires ${Math.round(waitMs / 1000)}s wait. Too long. Failing over to ${fallbackModel}\n`);
          currentModel = fallbackModel;
          attempt = -1;
          usedFallback = true;
          continue;
        }

        console.warn(`[LLMClient] Rate limit/transient error (${response.status}). Waiting ${Math.round(waitMs / 1000)}s before retrying...`);
        await sleep(waitMs);
        continue;
      }

      if (fallbackModel && currentModel !== fallbackModel && !usedFallback) {
        console.warn(`\n[LLMClient]\n${taskName} failed\nModel: ${currentModel}\nReason: API_ERROR_${response.status}\nFallback: ${fallbackModel}\n`);
        currentModel = fallbackModel;
        attempt = -1;
        usedFallback = true;
        continue;
      }

      console.error("[LLMClient] API Error:", response.status, response.statusText, bodyText.substring(0, 200));
      throw new Error(`LLM_PROVIDER_ERROR: ${response.status} ${response.statusText} - ${bodyText}`);
    }

    let data;
    try {
      data = JSON.parse(bodyText);
    } catch (err) {
      throw new Error(`LLM_PROVIDER_BAD_JSON: ${err.message}`);
    }

    return data.choices?.[0]?.message?.content || "";
  }

  console.error(`\n[LLMClient]\n${taskName} fallback\nPrimary: ${model}\nSecondary: ${fallbackModel || "none"}\nFallback: evaluation_fallback\n`);
  throw new Error("LLM_PROVIDER_ERROR: retry loop ended without a response.");
}

/**
 * Call the Groq LLM with system + user prompts. Returns parsed JSON.
 *
 * @param {object} opts
 * @param {string} opts.systemPrompt
 * @param {string} opts.userPrompt
 * @param {string} [opts.model]
 * @param {number} [opts.temperature=0]
 * @param {number} [opts.maxTokens=1200]
 * @returns {Promise<object>}
 */
async function callJsonLlm(opts) {
  console.log(`[LLMClient] Calling Groq with model: ${opts.model || "unknown"}`);

  const content = await callChatCompletion({ ...opts, jsonMode: true });
  console.log("[LLMClient] Received response (first 200 chars):", content.substring(0, 200));

  try {
    const parsed = parseJsonOnly(content);
    console.log("[LLMClient] Successfully parsed JSON");
    return parsed;
  } catch (parseErr) {
    console.warn("[LLMClient] JSON Parse Error. Attempting controlled repair...", parseErr.message);
    const repairPrompt = `You previously returned malformed JSON. Please return the identical content as valid JSON. Do not include markdown fences, thoughts, or explanations. ONLY return the raw JSON object.\n\nMalformed output:\n${content}`;
    
    try {
      const repairedContent = await callChatCompletion({
        ...opts,
        userPrompt: repairPrompt,
        taskName: "JSON_REPAIR",
        jsonMode: true
      });
      const repairedParsed = parseJsonOnly(repairedContent);
      console.log("[LLMClient] Successfully repaired JSON");
      return repairedParsed;
    } catch (repairErr) {
      console.error(`\n[LLMClient]\n${opts.taskName || "UNKNOWN_TASK"} fallback\nPrimary: ${opts.model}\nSecondary: ${opts.fallbackModel || "none"}\nFallback: evaluation_fallback\n`);
      throw new Error(`LLM_JSON_PARSE_ERROR_AND_REPAIR_FAILED: ${parseErr.message}`);
    }
  }
}

/**
 * Call the Groq LLM with system + user prompts. Returns raw text content.
 *
 * @param {object} opts
 * @param {string} opts.systemPrompt
 * @param {string} opts.userPrompt
 * @param {string} [opts.model]
 * @param {number} [opts.temperature=0]
 * @param {number} [opts.maxTokens=2500]
 * @returns {Promise<string>}
 */
async function rephraseQuestion(questionText) {
  const prompt = `You are an expert technical interviewer. The candidate has asked to clarify or rephrase the following question because they didn't understand it or said "I don't know".
Please rewrite the question to be simpler, clearer, and more direct, while still asking for the same core concept.
Do not provide the answer. Just provide the rephrased question.

Original Question: "${questionText}"
`;
  try {
    return await callTextLlm({
      systemPrompt: "You are a helpful technical interviewer.",
      userPrompt: prompt,
      model: process.env.GROQ_REPHRASE_MODEL,
      maxTokens: 300,
      taskName: "REPHRASE_QUESTION"
    });
  } catch (err) {
    console.error("[llmClient] Failed to rephrase question:", err);
    return "I'm having trouble rephrasing that right now. Could you please try to answer the original question to the best of your ability, or type Skip?";
  }
}

async function callTextLlm(opts) {
  console.log(`[LLMClient] Calling Groq (text mode) with model: ${opts.model || "unknown"}`);

  const content = await callChatCompletion(opts);
  console.log("[LLMClient] Received text response (first 200 chars):", content.substring(0, 200));

  return content;
}

module.exports = { callJsonLlm, callTextLlm, parseJsonOnly, rephraseQuestion };
